import { mkdirSync } from 'node:fs';
import { dirname, isAbsolute, join, resolve } from 'node:path';
import { DatabaseSync } from 'node:sqlite';
import { drizzle, type NodeSQLiteDatabase } from 'drizzle-orm/node-sqlite';
import { migrate } from 'drizzle-orm/node-sqlite/migrator';

export type Db = NodeSQLiteDatabase;

/** Migrations generated by drizzle-kit (apps/api/drizzle), shipped next to dist/. */
export const MIGRATIONS_FOLDER = join(
  import.meta.dirname,
  '..',
  '..',
  '..',
  'drizzle',
);

/** Opens (and creates) the SQLite file, enables FK enforcement and WAL, applies migrations. */
export function openDatabase(path: string): Db {
  const file = path === ':memory:' || isAbsolute(path) ? path : resolve(path);
  if (file !== ':memory:') mkdirSync(dirname(file), { recursive: true });
  const client = new DatabaseSync(file);
  client.exec(
    'PRAGMA foreign_keys = ON; PRAGMA journal_mode = WAL; PRAGMA busy_timeout = 5000;',
  );
  const db = drizzle({ client });
  migrate(db, { migrationsFolder: MIGRATIONS_FOLDER });
  return db;
}
